        events.append((end, 'b_end'))

    # Sort events by position, with a_start and b_end before a_end and b_start at same position
    events.sort(key=lambda x: (x[0], x[1] not in ['a_start', 'b_end']))

    result = []
    a_depth = 0  # Number of active a intervals
    b_depth = 0  # Number of active b intervals
    last_pos = None

    for pos, event_type in events:
        # If we transition from covered by a but not b to something else, record interval
        if last_pos is not None and a_depth > 0 and b_depth == 0 and pos > last_pos:
            result.append([last_pos, pos])

        # Update depths
        if event_type == 'a_start':
            a_depth += 1
        elif event_type == 'a_end':
            a_depth -= 1
        elif event_type == 'b_start':
            b_depth += 1
        elif event_type == 'b_end':
            b_depth -= 1

        last_pos = pos

    return _merge_intervals(result)


def _merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start position
    intervals.sort()

    merged = [intervals[0]]
    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            # Overlapping or touching, merge
            merged[-1][1] = max(merged[-1][1], end)
        else:
            # Disjoint, add new interval
            merged.append([start, end])

    return merged

